<template><section aria-label="JSON 工具箱"><p class="tool-note">校验、格式化或压缩 JSON。保留大整数原始数字和重复字段，不经过对象重新序列化。</p><div class="tool-actions"><label>缩进<select v-model="indent" aria-label="JSON 缩进"><option :value="2">2 空格</option><option :value="4">4 空格</option><option value="tab">Tab</option></select></label><button type="button" @click="run(false)">格式化 JSON</button><button type="button" @click="run(true)">压缩 JSON</button><button type="button" @click="showTree">树形查看</button><button type="button" @click="input = ''; output = ''; error = ''; message = ''; tree = null; treeError = ''">清空 JSON</button></div><div class="tool-two-column"><label class="tool-label">输入 JSON<textarea v-model="input" aria-label="输入 JSON" spellcheck="false" placeholder='{"hello":"01"}'></textarea></label><label class="tool-label">JSON 结果<textarea v-model="output" aria-label="JSON 结果" spellcheck="false"></textarea></label></div><JsonTreeNode v-if="tree" :node="tree" :depth="0" /><p v-if="treeError" class="tool-note">{{ treeError }}</p><p v-if="error" role="alert" class="tool-error">{{ error }}</p><div class="tool-actions"><button type="button" :disabled="!output" @click="copy">复制 JSON</button><button type="button" :disabled="!output" @click="download">下载 JSON</button></div><p role="status">{{ message }}</p></section></template>
<script>
import JsonTreeNode from './JsonTreeNode.vue';
import { formatJson, downloadBlob, buildJsonTree } from '../../utils/utility-tools.mjs';
export default { name: 'JsonTool', components: { JsonTreeNode }, data: () => ({ input: '', output: '', tree: null, treeError: '', indent: 2, error: '', message: '' }), methods: { showTree() { this.run(false); if (this.error) return; const result = buildJsonTree(this.input); this.tree = result.node || null; this.treeError = result.error || ''; }, run(compact) { this.tree = null; this.treeError = ''; this.message = ''; const result = formatJson(this.input, compact, this.indent); this.error = result.error ? (result.line ? `第 ${result.line} 行，第 ${result.column} 列：` : '') + result.error : ''; this.output = result.error ? '' : result.text; if (!result.error) this.message = 'JSON 校验与处理完成'; }, async copy() { try { await navigator.clipboard.writeText(this.output); this.message = '已复制 JSON'; } catch { this.message = '复制未完成，请选中结果手动复制'; } }, download() { const result = formatJson(this.output, true); if (result.error) { this.error = '结果不是有效 JSON，请先修正'; return; } downloadBlob(new Blob([this.output], { type: 'application/json' }), '01-data.json'); } } };
</script>
